diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..237acbc
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,39 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { cook } from "../src/domain/recipes.js";
+import { fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+const lotQty = (store, lot) => store.data.batches.find((b) => b.lot === lot).qty;
+
+test("cooking bechamel uses the milk lot that expires first (HD-1022, not HD-1026)", () => {
+  const store = fresh();
+  const bechamel = store.data.recipes.find((r) => r.name === "bechamel");
+  const result = cook(store, bechamel.id, bechamel.portions, { at });
+  const milk = result.find((r) => r.itemId === 2);
+  assert.deepEqual(milk.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(lotQty(store, "HD-1022"), 0);
+  assert.equal(lotQty(store, "HD-1026"), 8);
+});
+
+test("consume spills over to the next expiring batch", () => {
+  const store = fresh();
+  const used = consume(store, 2, 3, { at });
+  assert.deepEqual(used, [{ batchId: 4, qty: 2 }, { batchId: 3, qty: 1 }]);
+});
+
+test("FEFO: no expiry goes last; equal expiry by receivedOn, then id", () => {
+  const store = fresh();
+  store.data.batches.push(
+    { id: 100, itemId: 2, lot: "N", qty: 1, receivedOn: "2026-10-01", expires: null, location: "fridge" },
+    { id: 102, itemId: 2, lot: "B", qty: 1, receivedOn: "2026-10-20", expires: "2026-10-28", location: "fridge" },
+    { id: 101, itemId: 2, lot: "C", qty: 1, receivedOn: "2026-10-20", expires: "2026-10-28", location: "fridge" },
+    { id: 103, itemId: 2, lot: "A", qty: 1, receivedOn: "2026-10-19", expires: "2026-10-28", location: "fridge" },
+  );
+  const used = consume(store, 2, 14, { at });
+  assert.deepEqual(
+    used.map((u) => u.batchId),
+    [103, 101, 102, 4, 3, 100],
+  );
+});
